using System.ComponentModel;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class FetchDataTool
{
    [McpServerTool, Description("Fetches data from an external API endpoint")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        ILogger<FetchDataTool> logger,
        [Description("The API path to fetch (e.g. /users/1)")] string path)
    {
        logger.LogInformation("Fetching data from path: {Path}", path);

        var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync();
        logger.LogInformation("Successfully fetched {Length} chars", content.Length);

        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the given text")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        return
        [
            new(Microsoft.Extensions.AI.ChatRole.User,
                $"Please provide a {style} summary of the following text:\n\n{text}")
        ];
    }
}

